class TrieNode:
    def __init__(self):
        self.children = {}      # letter -> TrieNode
        self.end = False        # does a word end here?

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.end = True

    def _walk(self, text):
        node = self.root
        for ch in text:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    def search(self, word):
        node = self._walk(word)
        return node is not None and node.end

    def starts_with(self, prefix):
        return self._walk(prefix) is not None

t = Trie()
for w in ["card", "care", "cat"]:
    t.insert(w)
print(t.search("car"), t.starts_with("car"))   # False True
t.insert("car")
print(t.search("car"), t.search("ca"))         # True False

