class Node:
    def __init__(self):
        self.children = {}
        self.end = False

def build(words):
    root = Node()
    for w in words:
        node = root
        for ch in w:
            node = node.children.setdefault(ch, Node())
        node.end = True
    return root

def complete(root, prefix):
    """Every stored word that starts with prefix, in alphabetical order."""
    node = root
    for ch in prefix:                       # 1. walk to the prefix's node
        node = node.children.get(ch)
        if node is None:
            return []
    out = []
    def dfs(node, path):                    # 2. collect everything below it
        if node.end:
            out.append(path)
        for ch in sorted(node.children):    # sorted children -> alphabetical words
            dfs(node.children[ch], path + ch)
    dfs(node, prefix)
    return out

def matches(node, pattern, i=0):
    """True if some word matches pattern, where '.' is any one letter."""
    if i == len(pattern):
        return node.end
    if pattern[i] == ".":
        return any(matches(child, pattern, i + 1) for child in node.children.values())
    child = node.children.get(pattern[i])
    return child is not None and matches(child, pattern, i + 1)

root = build(["car", "card", "care", "cart", "cat", "dog"])
print(complete(root, "car"))    # ['car', 'card', 'care', 'cart']
print(complete(root, "do"))     # ['dog']
print(matches(root, "ca.e"))    # True  (care)
print(matches(root, "c.g"))     # False

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))    # everyone starts as their own root
        self.rank = [0] * n             # upper bound on each root's tree height

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])   # path compression
        return self.parent[x]

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False                # already in the same group
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra             # make ra the taller tree
        self.parent[rb] = ra            # shorter tree goes under the taller one
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1          # equal heights: the result is one taller
        return True

