def make_dsu(n):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # path halving
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        parent[rb] = ra
        return True

    return find, union

# 1. Count groups: start with n, subtract one per successful union
find, union = make_dsu(6)
groups = 6
for a, b in [(0, 1), (1, 2), (3, 4), (2, 0)]:
    if union(a, b):
        groups -= 1
    else:
        print("edge", (a, b), "closes a cycle")   # edge (2, 0) closes a cycle
print("groups:", groups)                           # groups: 3  ({0,1,2}, {3,4}, {5})

# 2. Kruskal's minimum spanning tree: cheapest edges first, skip any that close a cycle
edges = [(4, 0, 1), (1, 1, 2), (3, 0, 2), (2, 2, 3), (5, 1, 3)]   # (cost, a, b)
